CREATE TYPE "ProductEventType" AS ENUM ('IMPRESSION','VIEW','SEARCH_CLICK','WISHLIST_ADD','WISHLIST_REMOVE','ADD_TO_CART','REMOVE_FROM_CART','CHECKOUT_STARTED');
CREATE TABLE "product_analytics_events" ("id" TEXT NOT NULL,"event_key" TEXT NOT NULL,"type" "ProductEventType" NOT NULL,"product_id" TEXT NOT NULL,"variant_id" TEXT,"customer_id" TEXT,"session_id" TEXT NOT NULL,"district" "JharkhandDistrict","source" TEXT,"search_query" TEXT,"device" TEXT,"quantity" INTEGER,"price" DECIMAL(12,2),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "product_analytics_events_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "product_analytics_events_event_key_key" ON "product_analytics_events"("event_key"); CREATE INDEX "product_analytics_events_product_id_type_created_at_idx" ON "product_analytics_events"("product_id","type","created_at"); CREATE INDEX "product_analytics_events_search_query_created_at_idx" ON "product_analytics_events"("search_query","created_at"); CREATE INDEX "product_analytics_events_session_id_created_at_idx" ON "product_analytics_events"("session_id","created_at");
CREATE TABLE "product_daily_aggregates" ("id" TEXT NOT NULL,"product_id" TEXT NOT NULL,"date" DATE NOT NULL,"impressions" INTEGER NOT NULL DEFAULT 0,"views" INTEGER NOT NULL DEFAULT 0,"cart_adds" INTEGER NOT NULL DEFAULT 0,"checkouts" INTEGER NOT NULL DEFAULT 0,"purchases" INTEGER NOT NULL DEFAULT 0,"units_sold" INTEGER NOT NULL DEFAULT 0,"revenue" DECIMAL(14,2) NOT NULL DEFAULT 0,CONSTRAINT "product_daily_aggregates_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "product_daily_aggregates_product_id_date_key" ON "product_daily_aggregates"("product_id","date"); CREATE INDEX "product_daily_aggregates_date_idx" ON "product_daily_aggregates"("date");
CREATE TABLE "product_health_snapshots" ("id" TEXT NOT NULL,"product_id" TEXT NOT NULL,"score" INTEGER NOT NULL,"conversion_score" INTEGER NOT NULL,"content_score" INTEGER NOT NULL,"stock_score" INTEGER NOT NULL,"fulfilment_score" INTEGER NOT NULL,"recommendations" JSONB NOT NULL,"calculated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "product_health_snapshots_pkey" PRIMARY KEY ("id")); CREATE INDEX "product_health_snapshots_product_id_calculated_at_idx" ON "product_health_snapshots"("product_id","calculated_at");
ALTER TABLE "product_analytics_events" ADD CONSTRAINT "product_analytics_events_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "product_analytics_events" ADD CONSTRAINT "product_analytics_events_variant_id_fkey" FOREIGN KEY ("variant_id") REFERENCES "product_variants"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "product_analytics_events" ADD CONSTRAINT "product_analytics_events_customer_id_fkey" FOREIGN KEY ("customer_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "product_daily_aggregates" ADD CONSTRAINT "product_daily_aggregates_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "product_health_snapshots" ADD CONSTRAINT "product_health_snapshots_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE CASCADE ON UPDATE CASCADE;
